const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['repo', 'sc', 'script'], 'Owner', 'Get the GitHub repo link to deploy your own instance', async ({ sock, from, msg, cfg, sender, settings }) => {
  const imageUrl = settings.menuImageUrl || cfg.menuImageUrl;
  const match = cfg.repoUrl.match(/github\.com\/([^\/]+)\/([^\/]+)/);
  if (!match) {
    const text = `📦 ${cfg.repoUrl}`;
    return imageUrl
      ? sock.sendMessage(from, { image: { url: imageUrl }, caption: text }, { quoted: msg })
      : sock.sendMessage(from, { text }, { quoted: msg });
  }
  const [, owner, repoName] = match;
  try {
    const res = await fetch(`https://api.github.com/repos/${owner}/${repoName}`);
    const d = await res.json();
    if (d.message === 'Not Found') throw new Error('not found');
    const text =
`┌「 *${cfg.botName.toUpperCase()} REPO* 」
│
✦ Name: ${d.name}
✦ Owner: ${d.owner?.login}
✦ Stars: ${d.stargazers_count} ⭐
✦ Forks: ${d.forks_count} 🍴
✦ Watchers: ${d.watchers_count} 👁️
✦ Size: ${d.size} KB
✦ Updated: ${new Date(d.updated_at).toLocaleString()}
✦ Repo: ${d.html_url}
✦ Contact Developer: ${cfg.masterNumbers[0] || 'Not set'}
Description: ${d.description || 'No description.'}

Hey @${sender.split('@')[0]} 👋
_Don't forget to fork and star the repo!_ ⭐
└─`;
    if (imageUrl) {
      await sock.sendMessage(from, { image: { url: imageUrl }, caption: text, mentions: [sender] }, { quoted: msg });
    } else {
      await sock.sendMessage(from, { text, mentions: [sender] }, { quoted: msg });
    }
  } catch (e) {
    const fallbackText = `📦 *${cfg.botName} source code*\n\n${cfg.repoUrl}\n\nContact Developer: ${cfg.masterNumbers[0] || 'Not set'}\n\nStar ⭐ and fork 🍴 it if useful.`;
    if (imageUrl) {
      await sock.sendMessage(from, { image: { url: imageUrl }, caption: fallbackText }, { quoted: msg });
    } else {
      await sock.sendMessage(from, { text: fallbackText }, { quoted: msg });
    }
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
